import{_ as t,o as a,c as i,O as r}from"./chunks/framework.dbd1b522.js";const n="/imgs/headset_guides/KQDFg1J.jpeg",o="/imgs/headset_guides/4n6f4U3.webp",s="/imgs/headset_guides/5xzpTqa.webp",l="/imgs/headset_guides/vNPx656.webp",h="/imgs/headset_guides/R3Uwllz.webp",d="/imgs/headset_guides/2z0TD3L.jpeg",c="/imgs/headset_guides/hCi744w.webp",u="/imgs/headset_guides/zJeadXI.jpg",p="/imgs/headset_guides/1h7ex2y.jpg",m="/imgs/headset_guides/pXb2UVZ.webp",g="/imgs/headset_guides/MnaWjHw.webp",b="/imgs/headset_guides/rDOzTz8.jpg",f="/imgs/headset_guides/AbnMtn4.jpeg",y="/imgs/headset_guides/LRN45aM.jpg",I=JSON.parse('{"title":"Valve Index Build Guide","description":"Two proven ways to build a clean EyeTrackVR setup on the Valve Index, including mounts, camera placement and wiring.","frontmatter":{"title":"Valve Index Build Guide","description":"Two proven ways to build a clean EyeTrackVR setup on the Valve Index, including mounts, camera placement and wiring."},"headers":[],"relativePath":"headset_guides/valve_index.md","filePath":"headset_guides/valve_index.md","lastUpdated":1792278920000}'),w={name:"headset_guides/valve_index.md"};function k(x,e,v,_,E,V){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 class="text-[var(--font-accent)]" id="valve-index" tabindex="-1">Valve Index <a class="header-anchor" href="#valve-index" aria-label="Permalink to &quot;Valve Index {.text-[var(--font-accent)]}&quot;">​</a></h1><p>These are two proven/tested ways to do a clean ETVR build on the Valve Index. Don&#39;t treat this as a <em>must follow</em>, but a setup to go for if you don&#39;t have other plans.</p><h3 id="recommended-valve-index-lens-mounts" tabindex="-1">Recommended Valve Index lens mounts <a class="header-anchor" href="#recommended-valve-index-lens-mounts" aria-label="Permalink to &quot;Recommended Valve Index lens mounts&quot;">​</a></h3><p><a href="https://github.com/Physics-Dude/Phys-Index-EyetrackVR-HW/blob/main/ETVR%20ValveIndex%20Cam-LED%20Mount%20Rings/Index-EyetrackVRv4%20v18%20Print%20Me.stl" target="_blank" rel="noreferrer">Physics-Dude&#39;s 160° V18</a> (mirror the STL for left)</p><p><a href="https://makerworld.com/en/models/196741#profileId-217255" target="_blank" rel="noreferrer">Foow17&#39;s 130 / 160°</a></p><p><a href="https://makerworld.com/en/models/196791#profileId-217311" target="_blank" rel="noreferrer">Foow17&#39;s 130 / 160° VROPTICIAN</a></p><p><a href="https://github.com/Frosty704/indexwidmo-eyetrackvr" target="_blank" rel="noreferrer">Frosty704&#39;s 160/120° WidmoVR Mount</a></p><p>Please note due to the LED positioning, these will <strong>require you to use the included 110mm extensions included in the V4 Kit</strong></p><p><a href="https://docs.eyetrackvr.dev/how_to_build/led_v4_setup" target="_blank" rel="noreferrer">V4 LED Kit Assembly</a></p><h2 id="mutethecyberwolf-s-dev-frunk-mod" tabindex="-1">MUTEtheCyberwolf&#39;s DEV Frunk Mod: <a class="header-anchor" href="#mutethecyberwolf-s-dev-frunk-mod" aria-label="Permalink to &quot;MUTEtheCyberwolf&#39;s DEV Frunk Mod:&quot;">​</a></h2><p><img src="'+n+'" alt="Valve Index DEV Frunk mount with two XIAO cameras installed" loading="lazy" decoding="async"><img src="'+o+'" alt="Front view of the Valve Index fitted with the DEV Frunk eye tracking mount" loading="lazy" decoding="async"></p><h4 id="mod-details" tabindex="-1">Mod Details <a class="header-anchor" href="#mod-details" aria-label="Permalink to &quot;Mod Details&quot;">​</a></h4><p>The DEV Frunk is a popular choice for ETVR on the Index. Replacing the original index frunk entirely, it has multiple mounting points for both the XIAO&#39;s, a Vive Facial Tracker (or <a href="https://babble.diy/" target="_blank" rel="noreferrer">project babble!</a>), and cutouts for 30x30x7mm fans.</p><p>It also provides excellent ventilation simply due to the design being much more open, as well as a flip up design for the face tracker mount.</p><p>Combined, it creates a clean setup with no need for hot glue or alternatives to mount your hardware.</p><h4 id="extra-parts-needed" tabindex="-1">Extra Parts Needed: <a class="header-anchor" href="#extra-parts-needed" aria-label="Permalink to &quot;Extra Parts Needed:&quot;">​</a></h4><p>I recommend a screw kit like <a href="https://www.amazon.com/XOOL-Precision-Screwdriver-Extension-Smartphone/dp/B086SQZGLJ" target="_blank" rel="noreferrer">this</a> one</p><ul><li>1x T5 Torx Screwdriver</li><li>1x H3.0 Screwdriver</li><li>1x Soldering Iron for heat inserts</li><li>8x M4x8.1 Heat Inserts <a href="https://www.aliexpress.com/item/3256804349544912.html" target="_blank" rel="noreferrer">AliExpress</a> Choose Size: M4 (OD 6mm)50pcs | Color: Length 8mm</li><li>6x M4x10 Screws <a href="https://www.aliexpress.com/item/2251832624557792.html" target="_blank" rel="noreferrer">AliExpress</a> Choose Size: M4 20pcs | Length: 10mm</li><li>1x M4x30 Screws <a href="https://www.aliexpress.com/item/2251832624557792.html" target="_blank" rel="noreferrer">AliExpress</a> Choose Size: M4 20pcs | Length: 30mm</li></ul><h4 id="_3d-printed-mounts" tabindex="-1">3D Printed Mounts <a class="header-anchor" href="#_3d-printed-mounts" aria-label="Permalink to &quot;3D Printed Mounts&quot;">​</a></h4><p>Found at MUTEtheCyberwolf&#39;s <a href="https://github.com/MUTEtheCyberwolf/VALVE-INDEX-DEV-Frunk-1.0/tree/main/3D%20Print%20Files%20STL(Ascii)" target="_blank" rel="noreferrer">GitHub Repo</a></p><p>You will need to print:</p><ul><li>1x Coverplate for XIAO Retention Clip (Logo or no Logo)</li><li>1x XIAO Retention Clip (Letters or no Letters)</li><li>1x Eyetrack VR Prototype XIAO Mount.stl</li><li>1x FacialTrackerBeerHingeVIDEVFrunk1.stl</li><li>1x FacialTrackerBridgeVIDEVFrunk1.stl <ul><li>Alternatively, if you have the <a href="https://www.amazon.com/LDLrui-4-Port-Splitter-Multiport-Adapter/dp/B0BLHCD7FS" target="_blank" rel="noreferrer">LDLRUI USB HUB</a>, <a href="https://github.com/Frosty704/mods-eyetrackvr/blob/main/ldlrui%20case%20and%20bridge%20merged-FacialTrackerBridgeVIDEVFrunk1.stl" target="_blank" rel="noreferrer">this modified version</a> of the DEV Frunk Bridge can snap fit the hub onto the bridge. <a href="/imgs/headset_guides/kRvx56r.jpeg">Example</a></li></ul></li><li>1x ValveIndexDEVFrunk1.stl <ul><li>Alternatively, if you are interested in routing the ribbon cables internally, <a href="https://github.com/Frosty704/mods-eyetrackvr/blob/main/ValveIndexDEVFrunk1_MODIFIED.stl" target="_blank" rel="noreferrer">this modified DEV Frunk</a> has holes at the top for sliding through ribbon cables and power cables. <a href="/imgs/headset_guides/RcYQ8xd.jpg">Example</a></li></ul></li></ul><p><img src="https://github.com/MUTEtheCyberwolf/VALVE-INDEX-DEV-Frunk-1.0/assets/98415183/3b2b4fc2-a0ce-4641-8d0f-8fcac9271e34" alt="Exploded drawing of the Valve Index DEV Frunk 1.0 parts" loading="lazy" decoding="async"></p><h3 id="assembly-details" tabindex="-1">Assembly Details: <a class="header-anchor" href="#assembly-details" aria-label="Permalink to &quot;Assembly Details:&quot;">​</a></h3><h4 id="_1-heat-inserts" tabindex="-1">1. Heat Inserts <a class="header-anchor" href="#_1-heat-inserts" aria-label="Permalink to &quot;1. Heat Inserts&quot;">​</a></h4><ol><li>Start with inserting your heat inserts to the designated holes on the frunk. Place the heat inserts so the side with the smaller radius sits in the hole</li></ol><ul><li>When heating up the inserts, <strong>let the weight of the soldering iron do the work</strong>, they make take a few seconds to start moving on their own. <ul><li><strong>Do not push down</strong>, and remove the iron when they are level with the print. It doesn&#39;t need to be perfect, so take your time!</li></ul></li></ul><p><img src="'+s+'" alt="Heat set inserts being melted into the DEV Frunk 3D print" loading="lazy" decoding="async"></p><p>Bottom picture courtesy of amoistman</p><ol start="2"><li>Next, place a heat insert into the bigger hole of the facial tracker bridge</li></ol><p><img src="'+l+'" alt="Heat insert hole in the facial tracker bridge print" loading="lazy" decoding="async"></p><ol start="3"><li>Lastly, place another heat insert into the thick side of the beer hinge</li></ol><p><img src="'+h+'" alt="Heat insert hole in the beer hinge print" loading="lazy" decoding="async"></p><ol start="4"><li>Your finished heat inserts should look like this</li></ol><p><img src="'+d+'" alt="DEV Frunk print with all heat inserts installed and level" loading="lazy" decoding="async"></p><p>Picture courtesy of amoistman</p><h4 id="_2-screws" tabindex="-1">2. Screws <a class="header-anchor" href="#_2-screws" aria-label="Permalink to &quot;2. Screws&quot;">​</a></h4><p>Now you&#39;re done with the hardest part! We can move onto screwing in the XIAO Mount and Facial tracker bridge onto the frunk, into the heat inserts we just inserted.</p><ul><li>The XIAO mount should be placed so the longer side is not blocking the fan holes</li><li>If you have trouble screwing them in, try screwing them equally to distribute the pressure more evenly. <ul><li>Screw one a little, screw the opposite the same amount, repeat.</li></ul></li></ul><p><img src="'+c+'" alt="Diagram showing which holes take the M4 screws on the DEV Frunk" loading="lazy" decoding="async"></p><p>Two last things to screw in will be the beer hinge and vive facial tracker or babble case if you have it</p><ol><li>Place the smaller hole of the beer hinge inbetween the bridge&#39;s screw holes. <ul><li>Screwing in <strong>opposite</strong> of where the heat insert is. You should be screwing <em><strong>into</strong></em> the heat insert</li></ul></li></ol><p><img src="'+u+'" alt="Screwing into the heat insert from the back of the DEV Frunk print" loading="lazy" decoding="async"></p><ol start="2"><li><p>For the last screw, repeat the same steps, but line up your face tracker or babble case. Screw from the same direction, into the heat insert of the beer hinge. Use either an M4x10 or an M4x30. I find the M4x10 sometimes loses tension, while the M4x30 doesnt.</p></li><li><p>Your final result should look like this <img src="'+p+'" alt="Finished DEV Frunk with the M4 screws installed" loading="lazy" decoding="async"></p></li></ol><h4 id="_3-mounting-components" tabindex="-1">3. Mounting components <a class="header-anchor" href="#_3-mounting-components" aria-label="Permalink to &quot;3. Mounting components&quot;">​</a></h4><ol><li>You can now push the XIAO&#39;s into the mount, making sure they are down snug, if you haven&#39;t already.</li></ol><p><img src="'+m+'" alt="XIAO ESP32 cameras pushed into the DEV Frunk mount" loading="lazy" decoding="async"></p><ol start="2"><li>Place your V4 LED kit PCB into the middle of the XIAO Retention Clip. Ensure the hole in the PCB alligns with the small bump on the retention clip. You will have to slide it in and push it under the overhangs until they snap over the PCB.</li></ol><p><img src="'+g+'" alt="V4 LED kit PCB seated in the XIAO retention clip" loading="lazy" decoding="async"></p><ol start="3"><li>Route your V4 LED connectors through the coverplate holes prior to putting it on</li></ol><p><img src="'+b+'" alt="V4 LED connectors routed through the DEV Frunk coverplate holes" loading="lazy" decoding="async"></p><ol start="4"><li><p>Place the coverplate ontop of the LED PCB until the front of it snaps down and locks it over the retention clip.</p></li><li><p>Then you can slide the retention clip over your XIAO mount to keep them in place.</p></li></ol><h4 id="_4-replacing-frunk" tabindex="-1">4. Replacing frunk <a class="header-anchor" href="#_4-replacing-frunk" aria-label="Permalink to &quot;4. Replacing frunk&quot;">​</a></h4><p><strong>PLEASE UNPLUG YOUR INDEX FROM POWER BEFORE CONTINUING</strong></p><p>You must have a T5 Torx screwdriver to remove the original index frunk screws, we will use the same screws to hold the dev frunk in place.</p><p>Picture courtesy of iFixit</p><p><img src="'+f+'" alt="T5 screw locations on the Valve Index frunk, image courtesy of iFixit" loading="lazy" decoding="async"></p><ol><li>If you do not have fans, and are mounting a USB Hub infront, I recommend now plugging in the USB hub through the fan holes, as you won&#39;t be able to after dev frunk is screwed on.</li></ol><p>Alternatively, you can use the USB C port below the middle bottom screw, and passthrough a hub with a <a href="https://www.aliexpress.us/item/3256802596853859.html" target="_blank" rel="noreferrer">FEMALE USB-C/A to MALE USB A</a> cable</p><ol start="2"><li>Once the frunk is removed, line up your DEV Frunk and screw it back in the same way. Support it in a way you can screw in without it falling.</li></ol><p><img src="'+y+'" alt="DEV Frunk lined up and screwed back onto the Valve Index" loading="lazy" decoding="async"></p><h2 id="physics-dude-s-gumstick-usb-hub-dongle" tabindex="-1">Physics-Dude&#39;s Gumstick USB Hub Dongle <a class="header-anchor" href="#physics-dude-s-gumstick-usb-hub-dongle" aria-label="Permalink to &quot;Physics-Dude&#39;s Gumstick USB Hub Dongle&quot;">​</a></h2><p><img src="https://github.com/Physics-Dude/Phys-Index-EyetrackVR-HW/assets/22563517/77e4141b-7da7-4cb3-ab16-d8d761c91930" alt="Gumstick USB hub dongle installed on the Valve Index" loading="lazy" decoding="async"></p><h4 id="mod-details-1" tabindex="-1">Mod Details <a class="header-anchor" href="#mod-details-1" aria-label="Permalink to &quot;Mod Details&quot;">​</a></h4><p>Physics-Dude&#39;s Gumstick Dongle provides a way to cleanly install EyeTrackVR, all fitting into the frunk. It will require significantly more tinkering and ability to solder.</p><h3 id="installation-instructions-and-bom-available-on-physics-dude-s-repo" tabindex="-1">Installation instructions and BOM available on <a href="https://github.com/Physics-Dude/Phys-Index-EyetrackVR-HW/tree/main?tab=readme-ov-file#gum-stick-usb-hub-dongle" target="_blank" rel="noreferrer">Physics-Dude&#39;s Repo</a> <a class="header-anchor" href="#installation-instructions-and-bom-available-on-physics-dude-s-repo" aria-label="Permalink to &quot;Installation instructions and BOM available on [Physics-Dude&#39;s Repo](https://github.com/Physics-Dude/Phys-Index-EyetrackVR-HW/tree/main?tab=readme-ov-file#gum-stick-usb-hub-dongle)&quot;">​</a></h3>',66)])])}const P=t(w,[["render",k]]);export{I as __pageData,P as default};
